#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int MAX=1e9;
struct Edge {
    int to, cap, cost, type;
    Edge(int t=0,int c=0,int v=0,int ty=0): to(t), cap(c), cost(v), type(ty) {}
};
vector<int> adj[100000];
Edge edges[1000000];
int edgeCount;
int sink;
int C, d;

void setup(int sinkNode) {
    sink=sinkNode;
    for (int i=0; i<=sink; ++i) adj[i].clear();
    edgeCount=0;
}

void connect(int u, int v, int cap, int cost, int type) {
    adj[u].push_back(edgeCount);
    edges[edgeCount]=Edge(v,cap,cost,type);
    edgeCount++;
    adj[v].push_back(edgeCount);
    if (type==1) {
        edges[edgeCount]=Edge(u,0,-C+d,type);
        edgeCount++;
    } else {
        edges[edgeCount]=Edge(u,0,-cost,type);
        edgeCount++;
    }
}

int computeFlow() {
    int dist[100000], inQ[100000], parent[100000], q[100000];
    for (int i=0; i<=sink; ++i) {
        dist[i]=MAX;
        inQ[i]=0;
    }
    dist[sink]=0;
    int front=0, back=1;
    q[0]=0;
    while (front<back) {
        int u=q[front++];
        inQ[u]=0;
        for (int r:adj[u]) {
            int v=edges[r].to;
            if (edges[r].cap>0 && dist[u]+edges[r].cost<dist[v]) {
                dist[v]=dist[u]+edges[r].cost;
                parent[v]=r;
                if (!inQ[v]) {
                    inQ[v]=1;
                    q[back++]=v;
                }
            }
        }
    }
    if (dist[sink]==MAX) return -1;
    int current=sink;
    while (current!=0) {
        int r=parent[current];
        if (edges[r].type==1) {
            if ((r&1)==1) {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            } else {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            }
        }
        edges[r].cap--;
        edges[r^1].cap++;
        current=edges[r^1].to;
    }
    return dist[sink];
}

int main() {
    int n,m,k;
    cin>>n>>m>>k>>C>>d;
    setup(n*100+1);
    for (int i=1; i<=k; ++i) {
        int x; cin>>x;
        connect(0,x,1,0,0);
    }
    for (int i=1; i<=99; ++i) {
        connect(1+i*n,100*n+1,MAX,0,0);
    }
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=99; ++j) {
            connect(i+(j-1)*n,i+j*n,MAX,C,0);
        }
    }
    for (int i=1; i<=m; ++i) {
        int x,y; cin>>x>>y;
        for (int j=1; j<=99; ++j) {
            connect(x+(j-1)*n,y+j*n,MAX,C+d,1);
            connect(y+(j-1)*n,x+j*n,MAX,C+d,1);
        }
    }
    cout<<computeFlow()<<endl;
    return 0;
}
